const BASE_SPHINX_SCORE = 2;
const NO_SPHINX_SCORE = 0;

const MANY_TYPES_THRESHOLD = 3;

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

const countDistinctTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return NO_SPHINX_SCORE;
  const types = countDistinctTypes(army);
  if (types > MANY_TYPES_THRESHOLD) return 2 * (types - MANY_TYPES_THRESHOLD) - 1;
  return BASE_SPHINX_SCORE;
};

